    """Apply the zero-marker mask to the binary panel, recoloring foreground as 2."""
    h, w = len(grid), len(grid[0])
    candidates = []
    # The separator splits two equal-sized panels in the examples.
    for r, row in enumerate(grid):
        if r == h - r - 1 and len(set(row)) == 1:
            candidates.append(("row", r))
    for c in range(w):
        if c == w - c - 1 and len({grid[r][c] for r in range(h)}) == 1:
            candidates.append(("col", c))
    if len(candidates) != 1:
        raise ValueError(f"Expected one centered separator, found {candidates}")
    axis, split = candidates[0]
    if axis == "row":
        marker, data = grid[:split], grid[split + 1:]
    else:
        marker = [row[:split] for row in grid]
        data = [row[split + 1:] for row in grid]
    out = [[2 if value != 0 else 0 for value in row] for row in data]
    for r in range(len(out)):
        for c in range(len(out[r])):
            if marker[r][c] == 0:
                out[r][c] = 0
    return out
